codeExamples.code:
-- Unique countries (single column)
SELECT DISTINCT country
FROM customers;

-- Unique (country, city) combinations (multi-column)
SELECT DISTINCT country, city
FROM customers;

-- Count of unique customers (ignores NULL customer_id)
SELECT COUNT(DISTINCT customer_id) AS unique_customers
FROM orders;

-- These two produce the same result and typically the same plan
SELECT DISTINCT region FROM sales;
SELECT region FROM sales GROUP BY region;

-- NULLs collapse to a single row under DISTINCT
-- If region has values: 'East', 'East', NULL, NULL
SELECT DISTINCT region FROM sales;
-- returns: 'East', NULL   (one NULL row, not two)

-- But COUNT(DISTINCT region) ignores NULL entirely
SELECT COUNT(DISTINCT region) AS distinct_regions FROM sales;
-- returns 1  (only 'East'; NULL is not counted)
